def ph(en):
    return re.findall(r"\{(\w+)\}", en)
TYPES = {"n": "int", "days": "int", "total": "int"}
for lang, idx in (("en", 0), ("te", 1)):
    out = {"@@locale": lang}
    for k, v in S.items():
        text = v[idx]
        assert sorted(ph(v[0])) == sorted(ph(v[1])), k
        out[k] = text
        names = ph(v[0])
        if names:
            out["@" + k] = {"placeholders": {n: {"type": TYPES.get(n, "String")} for n in names}}
    path = os.path.join(ROOT, "lib", "l10n", "app_%s.arb" % lang)
    json.dump(out, open(path, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print(len(S), "keys")
